/bin/bash -lc "python - <<'PY'
from pathlib import Path
from babel.messages.pofile import read_po
import gettext
for lang in ('nl','pl','pt'):
    with open(f'sphinx/locale/{lang}/LC_MESSAGES/sphinx.po',encoding='utf-8') as f: cat=read_po(f, locale=None, abort_invalid=True)
    with open(f'sphinx/locale/{lang}/LC_MESSAGES/sphinx.mo','rb') as f: gt=gettext.GNUTranslations(f)
    mism=[]; missing=[]; unexpected=[]
    exp={}
    for m in cat:
        if not m.id: continue
        if isinstance(m.id,tuple):
            vals=m.string if isinstance(m.string,tuple) else ()
            for i,v in enumerate(vals): exp[(m.id[0],i)]=v
        elif m.string: exp[m.id]=m.string
    got={k:v for k,v in gt._catalog.items() if k"'!='"''}
    for k,v in exp.items():
        if k not in got: missing.append(k)
        elif got[k]"'!=v: mism.append((k,v,got[k]))
    unexpected=[k for k in got if k not in exp]
    print(lang,'"'expected',len(exp),'got',len(got),'missing',missing[:3],len(missing),'mismatch',mism[:3],len(mism),'unexpected',unexpected[:3],len(unexpected))
PY"

